CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, email text UNIQUE NOT NULL, password_hash text NOT NULL, suspended boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS organizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, suspended boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS memberships(organization_id uuid REFERENCES organizations ON DELETE CASCADE, user_id uuid REFERENCES users ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('OWNER','ADMIN','AGENT','VIEWER')), PRIMARY KEY(organization_id,user_id));
CREATE TABLE IF NOT EXISTS sessions(token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS bots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations, public_id uuid UNIQUE NOT NULL DEFAULT gen_random_uuid(), name text NOT NULL, greeting text NOT NULL DEFAULT 'Hi there! How can I help you today?', color text NOT NULL DEFAULT '#7258f5', published boolean NOT NULL DEFAULT false, UNIQUE(id,organization_id));
CREATE TABLE IF NOT EXISTS documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, bot_id uuid NOT NULL, name text NOT NULL, type text NOT NULL, object_key text NOT NULL, digest text NOT NULL, bytes integer NOT NULL, status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','processing','ready','failed')), chunks integer NOT NULL DEFAULT 0, error text, attempts integer NOT NULL DEFAULT 0, lease_id uuid, lease_until timestamptz, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(bot_id,organization_id) REFERENCES bots(id,organization_id), UNIQUE(bot_id,digest), UNIQUE(id,organization_id,bot_id));
CREATE TABLE IF NOT EXISTS chunks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), document_id uuid NOT NULL, organization_id uuid NOT NULL, bot_id uuid NOT NULL, page integer NOT NULL, ordinal integer NOT NULL, content text NOT NULL, embedding vector(1536), FOREIGN KEY(document_id,organization_id,bot_id) REFERENCES documents(id,organization_id,bot_id) ON DELETE CASCADE, UNIQUE(document_id,ordinal));
CREATE INDEX IF NOT EXISTS chunks_scope ON chunks(organization_id,bot_id);
CREATE INDEX IF NOT EXISTS chunks_search ON chunks USING gin(to_tsvector('english',content));
CREATE TABLE IF NOT EXISTS conversations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, bot_id uuid NOT NULL, visitor_hash text, title text NOT NULL DEFAULT 'New conversation', mode text NOT NULL DEFAULT 'ai' CHECK(mode IN ('ai','waiting','human','resolved')), version integer NOT NULL DEFAULT 0, pending_request uuid, pending_until timestamptz, agent_id uuid REFERENCES users, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(bot_id,organization_id) REFERENCES bots(id,organization_id), UNIQUE(id,organization_id));
CREATE TABLE IF NOT EXISTS messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL, organization_id uuid NOT NULL, role text NOT NULL CHECK(role IN ('customer','assistant','agent','system')), content text NOT NULL, citations jsonb NOT NULL DEFAULT '[]', request_id uuid, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(conversation_id,organization_id) REFERENCES conversations(id,organization_id) ON DELETE CASCADE, UNIQUE(conversation_id,request_id,role));
CREATE INDEX IF NOT EXISTS conversation_scope ON conversations(organization_id,bot_id,updated_at);
CREATE INDEX IF NOT EXISTS messages_conversation ON messages(conversation_id,created_at);
CREATE TABLE IF NOT EXISTS audit_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations, actor_id uuid REFERENCES users, action text NOT NULL, target_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS usage_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations, conversation_id uuid NOT NULL REFERENCES conversations, tokens integer NOT NULL, mode text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS rate_limits(key text PRIMARY KEY, count integer NOT NULL, expires_at timestamptz NOT NULL);
